# Line bundles and divisors on the projective plane -- the check behind the card.
# Standard library only.  Three roads to one answer, Pic(P^2) = Z, generated by a line L:
#   road 1: divisors by exact degree arithmetic; a degree-0 divisor is div of a ratio of forms
#   road 2: the gluing data of O(D), and its first Chern class as a winding number
#   road 3: Bezout, (2h)(3h) = 6, by elimination and by a parametrised circle, both exact
from fractions import Fraction as Fr
import cmath, math

L = {(0, 0, 1): 1}                                    # z: the line at infinity
C = {(2, 0, 0): 1, (0, 2, 0): 1, (0, 0, 2): -34}      # x^2 + y^2 - 34z^2: circle through (3, 5)
E = {(0, 2, 1): 1, (3, 0, 0): -1, (0, 0, 3): 2}       # y^2 z - x^3 + 2z^3: the cubic y^2 = x^3 - 2

def ev(F, p):
    return sum(c * p[0] ** a * p[1] ** b * p[2] ** e for (a, b, e), c in F.items())

def deg(F):
    ds = {sum(m) for m in F}
    assert len(ds) == 1                                # a form: every term has the same degree
    return ds.pop()

def pmul(p, q):                                       # one-variable polynomials, lowest power first
    r = [Fr(0)] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            r[i + j] += a * b
    return r

def comp(F, X, Y, Z):                                 # F(X(m), Y(m), Z(m))
    out = [Fr(0)]
    for (a, b, e), c in F.items():
        t = [Fr(c)]
        for poly, k in ((X, a), (Y, b), (Z, e)):
            for _ in range(k):
                t = pmul(t, poly)
        n = max(len(out), len(t))
        out = [(out[i] if i < len(out) else 0) + (t[i] if i < len(t) else 0) for i in range(n)]
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    return out

def divide(p, r):                                     # p / (m - r) by synthetic division
    q, acc = [], Fr(0)
    for c in reversed(p):
        acc = acc * r + c
        q.append(acc)
    return list(reversed(q[:-1])), q[-1]

def show(p, v):                                       # leading term first
    out = ""
    for k in range(len(p) - 1, -1, -1):
        c = p[k]
        if c == 0:
            continue
        s = ("-" if c < 0 else "+") if out else ("-" if c < 0 else "")
        a = abs(c)
        out += (" " + s + " " if out else s) + ("" if a == 1 and k else str(a)) + (v if k else "") + (f"^{k}" if k > 1 else "")
    return out or "0"

def winding(g, R, n=4000):                            # turns of g(t) as t goes once round |t| = R
    pts = [g(R * cmath.exp(2j * math.pi * k / n)) for k in range(n + 1)]
    return round(sum(cmath.phase(b / a) for a, b in zip(pts, pts[1:])) / (2 * math.pi))

print("road 1, divisors on P^2 by degree")
dL, dC, dE = deg(L), deg(C), deg(E)
print(f"deg L = {dL}, deg C = {dC}, deg E = {dE}: classes [L], {dC}[L], {dE}[L]; D = E - C - L has degree {dE - dC - dL}")
f = lambda p: Fr(ev(E, p), ev(C, p) * ev(L, p))
vals = [f((k, 2 * k, 3 * k)) for k in (1, 2, -5)]
print(f"f = E/(C L) at (1 : 2 : 3), scaled by 1, 2, -5: {', '.join(str(v) for v in vals)}")
sec = [sum(1 for a in range(d + 1) for b in range(d + 1 - a)) for d in (1, 2, 3)]
print(f"sections of O(d), d = 1, 2, 3: {sec[0]}, {sec[1]}, {sec[2]} monomials; (d + 1)(d + 2)/2 = 3, 6, 10")
print("road 2, gluing data and the first Chern class")
pts = [(1, 2, 3), (2, -1, 5), (7, 3, -2)]
local = lambda F, e, s=1: [Fr(ev(F, tuple(s * c for c in p)), (s * p[2]) ** e) for p in pts]   # F/z^e at 3 points, scaled by s
expo = lambda F: [e for e in range(7) if local(F, e) == local(F, e, 2)]   # the powers e that make F/z^e a function
eE, e3L = expo(E), expo({(0, 0, 3): 1})                # local equations of E and of 3L on the chart z != 0
p, ez = pts[0], eE[0]
lz, lx = Fr(ev(E, p), p[2] ** ez), Fr(ev(E, p), p[0] ** ez)
print(f"at (1 : 2 : 3): E = {ev(E, p)}, C = {ev(C, p)}, L = {ev(L, p)}; E/z^{ez} = {lz}, E/x^{ez} = {lx}, ratio {lz / lx}")
print(f"E/z^e is a function only for e in {eE}, and z^3/z^e for e in {e3L}: O(E) and O(3L) both glue by (x/z)^{ez}")
wt = winding(lambda t: t ** ez, 1)
print(f"winding of the transition (x/z)^{ez} once round |x/z| = 1: {wt}")
P, Q, R = (1, -1, 2), (1, 2, 1), 10
on = lambda F: (lambda t: ev(F, tuple(a + t * b for a, b in zip(P, Q))))
ws = [winding(on(F), R) for F in (L, C, E)]
wf = winding(lambda t: on(E)(t) / (on(C)(t) * on(L)(t)), R)
print(f"test line M through (1 : -1 : 2) and (1 : 2 : 1), |t| = {R}: zeros of L {ws[0]}, C {ws[1]}, E {ws[2]}, f {wf}")
print(f"windings at |t| = 0.5: L {winding(on(L), 0.5)}, C {winding(on(C), 0.5)}, E {winding(on(E), 0.5)}")
print("road 3, Bezout: C . E = (2h)(3h) = 6")
cub = [Fr(-36), Fr(0), Fr(1), Fr(1)]                   # 34 - x^2 = x^3 - 2, so x^3 + x^2 - 36 = 0
quad, rem = divide(cub, Fr(3))
print(f"eliminate y: {show(cub, 'x')} = (x - 3)({show(quad, 'x')}), remainder {rem}")
disc = quad[1] ** 2 - 4 * quad[2] * quad[0]
xs = [complex(3)] + [(-quad[1] + s * cmath.sqrt(disc)) / (2 * quad[2]) for s in (1, -1)]
sols = [(x, s * cmath.sqrt(34 - x * x)) for x in xs for s in (1, -1)]
nreal = sum(1 for x, y in sols if abs(x.imag) + abs(y.imag) < 1e-12)
print(f"x = 3, {xs[1].real:.6f} + {xs[1].imag:.6f}i, {xs[2].real:.6f} - {-xs[2].imag:.6f}i; y^2 = 34 - x^2 is never 0: {len(sols)} points, {nreal} real")
inf = [(a, b) for a, b in ((1, 1j), (1, -1j)) if ev(E, (a, b, 0)) == 0]
print(f"at infinity: C meets z = 0 at (1 : i : 0), (1 : -i : 0); E vanishes at neither: {len(inf)} common points")
X, Y, Z = [Fr(-3), Fr(-10), Fr(3)], [Fr(5), Fr(-6), Fr(-5)], [Fr(1), Fr(0), Fr(1)]
cphi, ephi = comp(C, X, Y, Z), comp(E, X, Y, Z)
print(f"circle by lines through (3, 5): x : y : z = {show(X, 'm')} : {show(Y, 'm')} : {show(Z, 'm')}; C = {show(cphi, 'm')}")
print(f"E on the circle: {show(ephi, 'm')}, degree {len(ephi) - 1} of 6: one root at m = infinity, the point (3, -5)")
quart, r0 = divide(ephi, Fr(-3, 5))
res = max(abs(sum(complex(c) * ((y - 5) / (x - 3)) ** k for k, c in enumerate(quart))) for x, y in sols[2:])
print(f"m = -3/5 is a root: {'yes' if r0 == 0 else 'no'}, the point (3, 5); the 4 complex points solve the rest: {'yes' if res < 1e-9 else 'no'}")
print("what breaks")
scale = Fr(ev(C, (2, 4, 6)), ev(L, (2, 4, 6))) / Fr(ev(C, (1, 2, 3)), ev(L, (1, 2, 3)))
print(f"mistake 1, C/L, degrees 2 and 1: the value at (2 : 4 : 6) is {scale} times the value at (1 : 2 : 3)")
print(f"mistake 2, real points only: {nreal} of {len(sols)}")
onL = [Fr(0)] * 4
for (a, b, e), c in E.items():
    if e == 0:
        onL[a] += c                                    # E(x, 1, 0), a polynomial in x
mL = next(k for k, c in enumerate(onL) if c != 0)
print(f"mistake 3, E on z = 0: {show(onL, 'x')}, so 1 distinct point, (0 : 1 : 0), multiplicity {mL}")
T = {(0, 2): 1, (3, 0): -1, (1, 0): 1}                # y^2 - x^3 + x, as {(power of x, power of y): coefficient}
ox, oy = max(b for a, b in T), max(a for a, b in T)   # pole orders at O: x takes each value at 2 points, y at 3
po = sorted({ox * a + oy * b for a in range(5) for b in range(ox) if ox * a + oy * b <= 8})
gaps = [k for k in range(9) if k not in po]
yq = [Fr(sum(c for (a, b), c in T.items() if a == 0 and b == j)) for j in range(3)]   # T at x = 0, in powers of y
mP = next(k for k, c in enumerate(yq) if c != 0)
print(f"mistake 4, torus y^2 = x^3 - x: pole orders at O of x^a y^b: {', '.join(map(str, po))}; gaps {', '.join(map(str, gaps))}; "
      f"div(x) = {mP}P - {po[1]}O, P = (0, 0)")
n, k = 255, 223
print(f"Reed-Solomon ({n}, {k}): a message is a section of O({k - 1}) on the line, at most {k - 1} zeros; distance {n - k + 1}, corrects {(n - k) // 2}")
print("exponential sequence: P^2 b2 1 = 0 + 1 + 0, Pic = Z; quartic b2 22 = 1 + 20 + 1, rank of Pic <= 20")
print(f"figure, circle radius {math.sqrt(34):.6f}; cubic from ({2 ** (1 / 3):.6f}, 0); real meeting points (3, 5), (3, -5)")
assert ws == [dL, dC, dE] and wf == dE - dC - dL and wt == ws[2]  # winding against degree and gluing
assert vals[0] == vals[1] == vals[2] == Fr(-65, 903) and eE == e3L == [dE]   # scaling against exponent count
assert sec == [(d + 1) * (d + 2) // 2 for d in (1, 2, 3)]
assert rem == 0 and pmul([Fr(-3), Fr(1)], quad) == cub and len(sols) == dC * dE and nreal == 2 and inf == [] and all(abs(y) > 1 for _, y in sols)
assert cphi == [0] and len(ephi) == dC * dE and r0 == 0 and res < 1e-9   # parametrisation against elimination
assert gaps == [1] and mP == po[1] == 2 and mL == dE and scale == 2 and winding(on(E), 0.5) == 0
print("ALL CHECKS PASS")
